def art(i):
    shapes=['<path d="M64 62L142 113L81 151Z"/><circle cx="142" cy="113" r="5"/>','<path d="M80 60h62v100H80zM90 75h42M90 86h42M90 97h24"/>','<path d="M110 34v152M34 110h152M56 56l108 108M56 164L164 56"/>','<path d="M62 128l32-48 29 37 35-55"/><circle cx="94" cy="80" r="5"/>'][i]
    return f'<svg viewBox="0 0 220 220" aria-hidden="true" focusable="false"><g fill="none" stroke="currentColor" stroke-width="1.3"><circle cx="110" cy="110" r="86"/><circle cx="110" cy="110" r="66" stroke-dasharray="2 7"/>{shapes}</g><circle cx="110" cy="24" r="4" fill="currentColor"/></svg>'

def cards():
    return '<div class="journal-grid">'+''.join(f'<a class="journal-card tone-{i}" href="/articles/{a[0]}"><div class="journal-art">{art(i)}<span>0{i+1}</span></div><div class="journal-card-copy"><div class="journal-meta">{a[1]} · {a[4]}</div><h3>{a[2]}</h3><p>{a[3]}</p><span class="journal-read">Читать статью <span aria-hidden="true">↗</span></span></div></a>' for i,a in enumerate(ARTICLES))+'</div>'

HEADER='<header><a href="/" class="brand" aria-label="Хорар, главная"><span class="brand-icon">✳</span> хорар<span class="beta">BETA</span></a><nav><a class="nav-link" href="/about">Как это работает</a><a class="nav-link" href="/">Задать вопрос ↗</a></nav></header>'
FOOTER='<footer><a class="brand" href="/">✳ хорар</a><a href="/articles">Статьи</a><a href="/about">Как это работает</a><a href="/technical">Для разработчиков</a></footer>'
def page(title,desc,body,path):
    return f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Хорар</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://dowidai-horary.vercel.app{path}"><link rel="icon" href="/static/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/static/style.css?v=4"></head><body>{HEADER}{body}{FOOTER}</body></html>'

folder=ROOT/'static'/'articles';folder.mkdir(exist_ok=True)
intro='<div class="journal-heading"><span class="eyebrow">БИБЛИОТЕКА ХОРАРА</span><h1>Вопросы о том,<br><em>как устроен хорар.</em></h1><p>Небольшие статьи о традиции, языке карты и границах наших знаний. Без сложного входа в тему.</p></div>'
(folder/'index.html').write_text(page('Статьи о хорарной астрологии','Что такое хорарная астрология: история, методы чтения карты и вопрос о научных основаниях.',f'<main class="journal-page">{intro}{cards()}<aside class="journal-note">Начните со знакомства или выберите тему. Ссылки на источники находятся рядом с соответствующими объяснениями. Материалы о традиции описывают её представления и не подтверждают точность предсказаний.</aside></main>','/articles'),encoding='utf-8')
for i,a in enumerate(ARTICLES):
    slug,category,title,description,reading,sections,takeaway=a
    toc='<nav class="reading-toc" aria-label="В этой статье">'+''.join(f'<a href="#part-{j}">{escape(h)}</a>' for j,(h,p) in enumerate(sections))+'</nav>'
    body=''.join(f'<section id="part-{j}"><h2>{h}</h2><p>{p}</p></section>' for j,(h,p) in enumerate(sections))
    nxt=ARTICLES[(i+1)%len(ARTICLES)]
    content=f'<main class="reading-page"><a class="reading-back" href="/articles">← Все статьи</a><div class="reading-header"><span class="eyebrow">{category.upper()} · {reading.upper()}</span><h1>{title}</h1><p class="lead">{description}</p><p class="reading-credit">Материал проекта «Хорар» · 23 октября 2026</p></div><div class="reading-layout">{toc}<article>{body}<aside class="reading-takeaway"><span class="eyebrow">ЧТО ВАЖНО ЗАПОМНИТЬ</span><p>{takeaway}</p></aside><a class="reading-next" href="/articles/{nxt[0]}"><span>ДАЛЬШЕ В БИБЛИОТЕКЕ</span><strong>{nxt[2]} ↗</strong></a></article></div></main>'
    (folder/(slug+'.html')).write_text(page(title,description,content,'/articles/'+slug),encoding='utf-8')
# Shared preview on the home page.
p=ROOT/'static'/'index.html';s=p.read_text(encoding='utf-8')
start='<section class="journal-preview" id="articles">'
if start not in s:
    teaser=start+'<div class="journal-preview-heading"><div><span class="eyebrow">ПОЗНАКОМИТЬСЯ С ТРАДИЦИЕЙ</span><h2>Прежде чем читать звёзды.</h2><p>Что такое хорар, как читают карту и на чём основаны объяснения.</p></div><a href="/articles">Все статьи ↗</a></div>'+cards()+'</section>'
    s=s.replace('<section class="closing">',teaser+'<section class="closing">')
s=s.replace('/static/style.css?v=3','/static/style.css?v=4')
s=s.replace('<nav><a href="/about"','<nav><a href="/articles" class="nav-link">Статьи</a><a href="/about"')
if '<footer><a class="brand" href="/">✳ хорар</a><a href="/articles">' not in s:
    s=s.replace('<footer><a class="brand" href="/">✳ хорар</a>','<footer><a class="brand" href="/">✳ хорар</a><a href="/articles">Статьи</a>')
p.write_text(s,encoding='utf-8')
for filename in ('about.html','technical.html'):
    p=ROOT/'static'/filename;s=p.read_text(encoding='utf-8')
    if 'Статьи о хораре</a>' in s: continue
    s=s.replace('<nav class="about-toc" aria-label="Об описании сервиса">','<nav class="about-toc" aria-label="Об описании сервиса"><a href="/articles">Статьи о хораре</a>');p.write_text(s,encoding='utf-8')
